    test('a key-like filename command runs byte-identically, no notice',
        () async {
      final shell = _RecordingShell();
      final tool = bt.shellTool(
        MemoryExecutionEnv(cwd: '/work', shell: shell),
        retryBackoff: Duration.zero,
