              },
              onError: (Object _) {
                _logBroken = true;
              },
            );
      }
      _output.add(chunk);
    }

    _stdoutSub = process.stdout
        .transform(utf8.decoder)
        .listen(
          fanOut,
          onError: (_) {},
          onDone: () {
            if (!stdoutDone.isCompleted) stdoutDone.complete();
          },
        );
    _stderrSub = process.stderr
        .transform(utf8.decoder)
        .listen(
          fanOut,
          onError: (_) {},
          onDone: () {
            if (!stderrDone.isCompleted) stderrDone.complete();
