        // leaked RAF fd would live for the whole fa process (issue #925).
        try {
          await _logSink.flush();
        } on Object {
          _logBroken = true;
        }
        try {
          await _logSink.close();
        } on Object {
          _logBroken = true;
        }
        _settled.complete();
      }),
    );
