+
+  String? lastCommand;
+  var result = const Ok(ShellExecResult(stdout: 'out', stderr: '', exitCode: 0));
+
+  @override
+  Future<Result<ShellExecResult, ExecutionError>> exec(
+    String command, {
+    ShellExecOptions? options,
+  }) async {
+    lastCommand = command;
+    return result;
+  }
