  }
}

Future<ApprovalOutcome> _requestDecision({
  required String toolName,
  required ApprovalTier tier,
  required Map<String, dynamic> arguments,
  required String reason,
}) async {
  final callback = prompt;
  if (callback == null) {
    return ApprovalOutcome.denied(
