    if (prunedLogs > 0) '$prunedLogs old job log(s) pruned',
  ];
  if (notes.isNotEmpty) {
    _cli.io.writeln(tuiWarning('⚠ bash_jobs: ${notes.join(' · ')}'));
  }
}

